values ('c3c15fe0-93c8-415b-94fb-7af095e3709a', 'meet-your-mind', 'Meet Your Mind', 'A free, interactive tour of the machinery behind every thought you have.', 'Before you can use psychology to your advantage, you need a working map of your own mind. In this free starter course you''ll meet your two thinking systems, learn why your brain lies to you (kindly), and complete your first self-portrait, all through videos that pause, ask, and listen.', 'Foundations', 'Beginner', 0, 'usd', null, 'lucid', '◐', '{"name":"Dr. Amara Okafor","title":"Clinical Psychologist","bio":"Amara spent twelve years in private practice translating CBT and ACT research into tools people actually use on a Tuesday afternoon."}'::jsonb, array['Name your two modes of thinking and catch them in action', 'Spot three everyday mental shortcuts steering your choices', 'Build a first ''self-portrait'' you''ll refine across Pintevact']::text[], true, true, 0)
