values ('d73da563-45c6-42d2-a25e-c8f6356dec0d', 'emotional-alchemy', 'Emotional Alchemy', 'Turn anxiety, anger and overwhelm into information, and then into action.', 'Emotions aren''t problems to fix; they''re data to decode. Drawing on CBT, ACT and affect-labelling research, Emotional Alchemy teaches you to name what you feel with precision, defuse spiralling thoughts, and respond instead of react. Every lesson pauses to have you practice on your own real feelings.', 'Emotions', 'Beginner', 7900, 'usd', null, 'ember', '✺', '{"name":"Dr. Amara Okafor","title":"Clinical Psychologist","bio":"Amara spent twelve years in private practice translating CBT and ACT research into tools people actually use on a Tuesday afternoon."}'::jsonb, array['Expand your emotional vocabulary beyond ''fine'', ''stressed'' and ''tired''', 'Use cognitive defusion to unhook from sticky thoughts in under a minute', 'Build a personal regulation toolkit for high-pressure moments']::text[], true, true, 1)
