values ('7acd948c-7632-4cfd-ab3c-59ad3f77f17f', 'd73da563-45c6-42d2-a25e-c8f6356dec0d', 'dec7d30e-36c4-436b-b870-2ecf0633dbfa', 'you-are-not-your-thoughts', 'You Are Not Your Thoughts', 'Cognitive defusion: watch thoughts like passing cars instead of jumping in front of them.', 660, null, false, 2, '[{"atSeconds":0,"title":"The spark"},{"atSeconds":198,"title":"What the research says"},{"atSeconds":449,"title":"Make it yours"}]'::jsonb, array['Thoughts are mental events, not facts or commands.', 'Prefixing ''I''m having the thought that…'' creates instant distance.', 'Fighting a thought often strengthens it (ironic process theory).']::text[], 'Write your harshest recurring self-criticism. Now rewrite it as ''I notice I''m having the thought that…''. Read both aloud.')
